def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(x for x in counts if x != bg)
    out = [row[:] for row in grid]

    # Locate a closed rectangular outline of the non-background color.
    best = None
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    if (all(grid[r0][c] == fg and grid[r1][c] == fg
                            for c in range(c0, c1 + 1))
                        and all(grid[r][c0] == fg and grid[r][c1] == fg
                                for r in range(r0, r1 + 1))):
                        area = (r1-r0-1) * (c1-c0-1)
                        if best is None or area > best[0]:
                            best = (area, r0, r1, c0, c1)
    if best:
        _, r0, r1, c0, c1 = best
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if grid[r][c] == bg:
                    out[r][c] = 4
    return out
